const ECONOMICS_DP = [{"id": "3.1.1.1", "unit": 3, "topic": "T1 - International trade", "subtopic": "S1 - Key economic terminology", "code": "3.1.1.1", "descriptor": "Comprehend and describe key concepts using economic terminology, including absolute advantage, comparative advantage, competitive advantage, currency devaluation, currency revaluation, economic integration, economic union, exchange rate appreciation and depreciation, external stability, internal stability, factor endowment, exchange rates (fixed, floating and managed), free trade, sustainable economic growth, trade liberalisation, balance of payments, balance of trade, capital and financial account, current account deficit, current account, foreign investment, foreign debt, and terms of trade.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Absolute/comparative/competitive advantage describe different reasons a country benefits from specialising and trading: absolute advantage means producing more output from the same inputs, comparative advantage means producing at a lower opportunity cost, and competitive advantage means a firm/nation's edge from cost, innovation or branding.", "Exchange rate terms: appreciation/depreciation describe a floating currency's value rising/falling due to market forces, while devaluation/revaluation describe a deliberate government/central bank decision to lower/raise a fixed or managed currency's value.", "External stability refers to a sustainable balance of payments and manageable foreign debt; internal stability refers to low, stable inflation alongside full employment domestically.", "The balance of payments records all of a country's transactions with the rest of the world, split into the current account (trade in goods/services, income, transfers) and the capital and financial account (investment flows, asset transactions); the balance of trade is specifically the difference between exports and imports of goods and services."]}, {"id": "3.1.2.1", "unit": 3, "topic": "T1 - International trade", "subtopic": "S2 - The circular flow and the open economy", "code": "3.1.2.1", "descriptor": "Comprehend the concept of an open economy to explain how it operates in terms of the circular flow of income model.", "graphical": false, "needsExplanation": true, "modelAnswer": ["An open economy is one that engages in international trade and financial flows with the rest of the world, unlike a closed economy which has no external transactions.", "In the circular flow of income model, opening the economy adds two new leakages (imports and net flows out of the financial sector overseas) and two new injections (exports and foreign investment/capital inflow) to the basic household-firm flow.", "For the economy to be in equilibrium, total injections (investment, government spending, exports, foreign investment) must equal total leakages (savings, taxation, imports, outflows) — an open economy adds extra channels through which this balance can be disturbed or restored."]}, {"id": "3.1.3.1", "unit": 3, "topic": "T1 - International trade", "subtopic": "S3 - Advantages and disadvantages of trade", "code": "3.1.3.1", "descriptor": "Comprehend and explain the advantages and disadvantages of international trade, and how trade can impact economic policy, including sustainable economic growth, and external and internal stability.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Advantages of international trade include access to a wider range and lower-cost range of goods/services, economies of scale from larger export markets, increased competition driving efficiency and innovation, and higher incomes/living standards from specialisation.", "Disadvantages can include structural unemployment as domestic industries unable to compete are displaced, greater exposure to global economic shocks, potential loss of self-sufficiency in key industries, and unequal distribution of the gains from trade.", "Trade affects economic policy by influencing decisions aimed at sustainable economic growth (balancing export/import-led growth with environmental and social costs) and external stability (managing the balance of payments and foreign debt), while also feeding into internal stability via competitive pressure on domestic prices and employment."]}, {"id": "3.1.4.1", "unit": 3, "topic": "T1 - International trade", "subtopic": "S4 - Australia's trade patterns and trends", "code": "3.1.4.1", "descriptor": "Analyse the composition and direction of Australia's trade patterns (e.g. the five largest importers and exporters), compare them to emerging patterns and trends in international trade, and calculate the percentage change from one period to the next.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Composition refers to WHAT Australia trades (e.g. the mix of commodities, manufactured goods and services in exports/imports); direction refers to WHO Australia trades with (its major trading partner countries).", "Analysing patterns involves identifying which commodities/partners dominate, whether reliance is concentrated (e.g. heavy dependence on a few commodities or partners) or diversified, and how this compares with global/emerging trends (e.g. the rising importance of services trade or particular regions).", "Comparing to emerging trends means considering shifts such as the growth of intra-Asian trade, digital/services trade, or new trading partners, and evaluating what this could mean for Australia's future trade composition and direction."]}, {"id": "3.1.4.2", "unit": 3, "topic": "T1 - International trade", "subtopic": "S4 - Australia's trade patterns and trends", "code": "3.1.4.2", "descriptor": "Calculate the percentage change from one period to the next in trade data.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.1.5.1", "unit": 3, "topic": "T1 - International trade", "subtopic": "S5 - Trade theories", "code": "3.1.5.1", "descriptor": "Comprehend and explain the development and contemporary relevance of trade theories, including the economic theories of absolute (see Adam Smith), comparative (see David Ricardo) and competitive advantage (see Michael Porter).", "graphical": false, "needsExplanation": true, "modelAnswer": ["Absolute advantage (Adam Smith) argues countries should specialise in producing goods they can make using fewer resources (more efficiently) than other countries, then trade for what others produce more efficiently.", "Comparative advantage (David Ricardo) extended this idea, showing that even a country with no absolute advantage in anything can still gain from trade by specialising in the good it produces at the lowest opportunity cost relative to its other production options.", "Competitive advantage (Michael Porter) is a more contemporary, firm/industry-level theory, arguing that a nation's success in an industry depends on factors like innovation, firm strategy, related/supporting industries and demand conditions — not just natural resource endowments.", "These theories remain relevant today for explaining why global supply chains and specialisation patterns exist, though critics note they can understate the role of technology, government policy and economies of scale in shaping modern trade patterns."]}, {"id": "3.1.5.2", "unit": 3, "topic": "T1 - International trade", "subtopic": "S5 - Trade theories", "code": "3.1.5.2", "descriptor": "Apply trade theories (absolute, comparative and competitive advantage) using relevant diagrams and models.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.1.6.1", "unit": 3, "topic": "T1 - International trade", "subtopic": "S6 - Floating exchange rates", "code": "3.1.6.1", "descriptor": "Comprehend and explain demand and supply factors in a floating exchange rate system.", "graphical": false, "needsExplanation": true, "modelAnswer": ["In a floating exchange rate system, the value of a currency is determined purely by market demand for and supply of that currency, without direct government/central bank intervention.", "Demand for the Australian dollar comes from foreigners wanting to buy Australian exports, invest in Australian assets, or hold AUD for other reasons; supply of the Australian dollar comes from Australians wanting to buy imports, invest overseas, or convert AUD into other currencies.", "An increase in demand for AUD (or a decrease in supply) causes the currency to appreciate; a decrease in demand (or an increase in supply) causes it to depreciate — the exchange rate continuously adjusts to equate the two."]}, {"id": "3.1.6.2", "unit": 3, "topic": "T1 - International trade", "subtopic": "S6 - Floating exchange rates", "code": "3.1.6.2", "descriptor": "Construct diagrams applying demand and supply factors in a floating exchange rate system.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.1.6.3", "unit": 3, "topic": "T1 - International trade", "subtopic": "S6 - Floating exchange rates", "code": "3.1.6.3", "descriptor": "Comprehend and explain the factors underlying the demand and supply of the Australian currency and how a floating exchange rate insulates the Australian economy from external shocks.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Factors affecting AUD demand/supply include relative interest rates, commodity prices (especially for a resource-exporting economy like Australia), relative inflation rates, speculation, and the terms of trade.", "A floating exchange rate provides an automatic 'shock absorber': if an external shock reduces demand for Australian exports, the AUD depreciates, which makes exports cheaper and imports more expensive, helping to restore competitiveness and partially offset the shock's impact on the economy.", "Because this adjustment happens automatically through market forces (rather than requiring deliberate policy action), a floating exchange rate is said to insulate the domestic economy from the full impact of external shocks, compared with a fixed exchange rate where no such automatic adjustment occurs."]}, {"id": "3.1.7.1", "unit": 3, "topic": "T1 - International trade", "subtopic": "S7 - Terms of trade and exchange rate policy responses", "code": "3.1.7.1", "descriptor": "Select data and information to analyse and evaluate the effects of changes in Australia's terms of trade on the economy from a range of perspectives.", "graphical": false, "needsExplanation": true, "modelAnswer": ["The terms of trade measures the ratio of export prices to import prices; an improvement (rise) means Australia can buy more imports for the same quantity of exports, effectively raising national income.", "An improving terms of trade generally benefits exporters and the government (via higher royalty/tax revenue from resource exports) and can support higher national income and living standards, but may also contribute to currency appreciation that disadvantages other export-competing industries (a 'two-speed economy' effect).", "A deteriorating terms of trade has the opposite effects — squeezing export revenue and national income — and evaluating its impact requires weighing perspectives of different groups (resource exporters vs. import-competing industries vs. consumers vs. government revenue)."]}, {"id": "3.1.7.2", "unit": 3, "topic": "T1 - International trade", "subtopic": "S7 - Terms of trade and exchange rate policy responses", "code": "3.1.7.2", "descriptor": "Select data and information to analyse and evaluate the causes of exchange rate appreciation or depreciation movements.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Causes of appreciation include rising relative interest rates (attracting foreign capital seeking higher returns), rising commodity/export prices, improving terms of trade, and positive market sentiment/speculation about the economy.", "Causes of depreciation include falling relative interest rates, falling commodity/export prices, deteriorating terms of trade, and negative speculation or capital outflow.", "Evaluating a specific movement involves weighing which of these factors (interest rate differentials, commodity prices, speculation, terms of trade) most plausibly explains the observed change, using current data and reasoning about their relative strength at the time."]}, {"id": "3.1.7.3", "unit": 3, "topic": "T1 - International trade", "subtopic": "S7 - Terms of trade and exchange rate policy responses", "code": "3.1.7.3", "descriptor": "Select data and information to analyse and evaluate government policy responses to exchange rate movements and changing trade relationships using criteria, e.g. employment in trade-exposed industries, economic growth, efficiency (allocative and dynamic costs), and importation of goods and services.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Policy responses to exchange rate movements can include monetary policy adjustments (interest rates affecting capital flows and thus the currency), direct intervention in currency markets (less common under a float), or fiscal/industry support for trade-exposed sectors affected by currency swings.", "Evaluating these responses means weighing them against multiple criteria: effects on employment in trade-exposed industries, overall economic growth, efficiency (whether the response distorts resource allocation, i.e. allocative costs, or discourages innovation, i.e. dynamic costs), and effects on the cost/availability of imported goods and services.", "A well-rounded evaluation considers trade-offs — e.g. a policy that protects trade-exposed jobs in the short term might reduce overall efficiency or raise import costs, requiring judgement about which objective should be prioritised in the circumstances."]}, {"id": "3.1.8.1", "unit": 3, "topic": "T1 - International trade", "subtopic": "S8 - Balance of payments accounts", "code": "3.1.8.1", "descriptor": "Comprehend, explain and classify a country's international transactions into current and capital account statements.", "graphical": false, "needsExplanation": true, "modelAnswer": ["The current account records trade in goods and services (exports minus imports), primary income (e.g. investment income, wages), and secondary income (transfers such as foreign aid or remittances).", "The capital and financial account records transactions in financial assets and liabilities between Australia and the rest of the world, including foreign direct investment, portfolio investment, and other capital flows.", "Classifying a transaction correctly requires identifying whether it reflects the flow of goods/services/income (current account) or the flow of financial assets/capital ownership (capital and financial account) — by construction, in principle the two accounts sum to (approximately) balance overall."]}, {"id": "3.1.9.1", "unit": 3, "topic": "T1 - International trade", "subtopic": "S9 - Foreign investment", "code": "3.1.9.1", "descriptor": "Comprehend and explain the significance of foreign investment to Australian economic development, e.g. to finance mining booms.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Foreign investment brings in capital that Australia can use to fund large-scale projects (such as mining and infrastructure booms) that might otherwise be constrained by limited domestic savings.", "It can also bring technology transfer, management expertise, and access to global supply chains and export markets, supporting productivity growth beyond just the capital itself.", "However, reliance on foreign investment also means a growing stock of foreign liabilities (foreign debt/equity), meaning future income outflows (interest and profit repatriation) that must be weighed against the benefits of the investment inflow."]}, {"id": "3.1.10.1", "unit": 3, "topic": "T1 - International trade", "subtopic": "S10 - Balance of payments trends", "code": "3.1.10.1", "descriptor": "Select data and information to analyse and evaluate patterns of Australia's balance of payments including the current account and balance of trade over the last 5 or 10 years, including the percentage change.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Analysing BOP patterns over time involves identifying trends in the current account balance (surplus/deficit) and balance of trade, and relating these to underlying drivers such as commodity price cycles, exchange rate movements, and domestic/global demand conditions.", "A persistent current account deficit indicates the country is a net borrower from the rest of the world over that period, while a move toward surplus (as Australia has experienced during resource-export booms) indicates the reverse.", "Evaluating these trends means considering whether they reflect sustainable structural changes (e.g. a genuinely more trade-competitive economy) or temporary cyclical factors (e.g. a commodity price spike), which has different implications for future economic policy."]}, {"id": "3.1.10.2", "unit": 3, "topic": "T1 - International trade", "subtopic": "S10 - Balance of payments trends", "code": "3.1.10.2", "descriptor": "Calculate the percentage change in balance of payments data, including the current account and balance of trade, over the last 5 or 10 years.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.1.10.3", "unit": 3, "topic": "T1 - International trade", "subtopic": "S10 - Balance of payments trends", "code": "3.1.10.3", "descriptor": "Select data and information to analyse and evaluate cyclical and structural causes and effects of Australian current and capital account trends.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Cyclical causes are temporary, tied to the business cycle or short-term price swings (e.g. a temporary commodity price spike improving the current account), and tend to reverse as conditions normalise.", "Structural causes reflect longer-term, more permanent shifts in the economy (e.g. a genuine change in Australia's competitiveness, demographic shifts affecting savings, or a permanent change in industry composition).", "Distinguishing between the two matters for evaluating the effects: cyclical trends may not require policy action (they'll likely self-correct), whereas structural trends may need deliberate policy responses to address underlying, persistent imbalances."]}, {"id": "3.1.10.4", "unit": 3, "topic": "T1 - International trade", "subtopic": "S10 - Balance of payments trends", "code": "3.1.10.4", "descriptor": "Select data and information to analyse and evaluate the significance of movements within the balance of payments on the domestic economy, from a variety of perspectives, e.g. import and export suppliers, and buyers.", "graphical": false, "needsExplanation": true, "modelAnswer": ["A current account deficit or surplus movement affects different groups differently — e.g. export suppliers benefit from a weaker currency (following a deficit) as their goods become more price-competitive overseas, while import buyers face higher costs for the same weaker currency.", "Movements in the capital and financial account (e.g. large inflows of foreign investment) can affect domestic interest rates, asset prices, and the exchange rate, with flow-on effects for borrowers, savers, and different industries.", "A balanced evaluation weighs these varied, sometimes opposing, perspectives — recognising that a BOP movement rarely affects all sectors of the economy in the same way or to the same degree."]}, {"id": "3.1.10.5", "unit": 3, "topic": "T1 - International trade", "subtopic": "S10 - Balance of payments trends", "code": "3.1.10.5", "descriptor": "Select data and information to analyse and evaluate the significance of Australia's foreign debt position and foreign investment longitudinally.", "graphical": false, "needsExplanation": true, "modelAnswer": ["A growing foreign debt position means increasing future obligations to service that debt (interest payments), which represents an ongoing leakage from the current account (as income outflows) even after the initial capital inflow has been spent.", "Evaluating significance over time (longitudinally) involves considering whether the debt has funded productive, income-generating investment (which can help service the debt sustainably) or unproductive consumption (which raises sustainability concerns).", "The trend in foreign debt as a proportion of GDP, rather than its absolute level, is often a more meaningful measure of whether Australia's foreign liabilities are becoming more or less manageable over time."]}, {"id": "3.1.11.1", "unit": 3, "topic": "T1 - International trade", "subtopic": "S11 - Communicating economic responses", "code": "3.1.11.1", "descriptor": "Create responses that communicate economic meaning using data, information, graphs and diagrams to suit the intended purpose in paragraphs and extended responses.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.2.1.1", "unit": 3, "topic": "T2 - Global economic issues", "subtopic": "S1 - Key terminology (trade protection and globalisation)", "code": "3.2.1.1", "descriptor": "Describe key concepts using economic terminology, including methods of trade protection, economic integration, economic union, globalisation and trade liberalisation.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Methods of trade protection are government measures that shield domestic industries from foreign competition, such as tariffs (taxes on imports), subsidies (payments to domestic producers), and quotas (limits on import quantities).", "Economic integration describes countries progressively reducing barriers between their economies (e.g. through trade agreements), while an economic union represents a deeper form of integration involving a common market and coordinated economic policy (e.g. shared currency or regulations).", "Globalisation refers to the increasing interconnectedness of economies worldwide through trade, investment, technology and cultural exchange; trade liberalisation refers specifically to the process of reducing/removing trade barriers to allow freer trade between countries."]}, {"id": "3.2.2.1", "unit": 3, "topic": "T2 - Global economic issues", "subtopic": "S2 - Factors driving supply chain integration and globalisation", "code": "3.2.2.1", "descriptor": "Explain, analyse and evaluate the factors that have contributed to the growth of multi-company and multinational supply chain integration, e.g. the location of natural factor endowments; digital and other innovation; infrastructure (including logistics); and government incentives.", "graphical": false, "needsExplanation": true, "modelAnswer": ["The location of natural factor endowments (resources, labour, land) drives firms to source inputs or locate production stages in countries with a comparative advantage in that resource, spreading a single product's supply chain across multiple countries.", "Digital and other innovation (e.g. improved communication technology, real-time tracking, automation) has made it easier and cheaper to coordinate complex, geographically dispersed supply chains than in the past.", "Improved infrastructure and logistics (ports, shipping, freight networks) reduce the time and cost of moving goods between countries, while government incentives (tax breaks, special economic zones, trade agreements) actively encourage firms to integrate production across borders."]}, {"id": "3.2.2.2", "unit": 3, "topic": "T2 - Global economic issues", "subtopic": "S2 - Factors driving supply chain integration and globalisation", "code": "3.2.2.2", "descriptor": "Explain, analyse and evaluate the factors that have contributed to globalisation and current international trade patterns, including technology; multi-national corporations; regional trading blocs; and deregulation of financial capital markets and of non-government institutions, e.g. the World Trade Organization, International Monetary Fund and World Bank.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Technology (transport, communications, the internet) has dramatically lowered the cost and time of moving goods, services, capital and information across borders, enabling far more integrated global trade and production.", "Multinational corporations actively drive globalisation by establishing operations, supply chains and markets across many countries in pursuit of efficiency and profit.", "Regional trading blocs (e.g. free trade areas, customs unions) reduce barriers between member countries, encouraging trade growth within the bloc and shaping broader global trade patterns.", "Deregulation of financial capital markets has made it easier for capital to flow freely between countries, while international institutions like the WTO, IMF and World Bank have promoted rules-based trade liberalisation and provided frameworks/support for global economic cooperation."]}, {"id": "3.2.3.1", "unit": 3, "topic": "T2 - Global economic issues", "subtopic": "S3 - Trade protection methods", "code": "3.2.3.1", "descriptor": "Explain the methods of protection employed by nations, including tariffs and non-tariff barriers (e.g. subsidies, quotas and bureaucratic requirements).", "graphical": false, "needsExplanation": true, "modelAnswer": ["A tariff is a tax imposed on imported goods, raising their price to domestic consumers and making domestically produced substitutes relatively more competitive.", "A subsidy is a payment made by the government to domestic producers, lowering their production costs and allowing them to sell at more competitive prices without necessarily raising the price faced by consumers.", "A quota is a limit on the physical quantity of a good that can be imported, restricting supply and thereby favouring domestic production of the same good.", "Bureaucratic requirements (e.g. complex customs procedures, product standards, licensing requirements) act as a non-tariff barrier by raising the time and compliance cost of importing, discouraging foreign competition without formally taxing or limiting quantities."]}, {"id": "3.2.3.2", "unit": 3, "topic": "T2 - Global economic issues", "subtopic": "S3 - Trade protection methods", "code": "3.2.3.2", "descriptor": "Construct supply and demand diagrams to demonstrate the effect of methods of trade protection, including tariffs and non-tariff barriers.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.2.4.1", "unit": 3, "topic": "T2 - Global economic issues", "subtopic": "S4 - Protectionism vs trade liberalisation", "code": "3.2.4.1", "descriptor": "Analyse and evaluate the economic arguments for and against protectionism and trade liberalisation responses from different viewpoints using economic criteria (e.g. economic efficiency, economic growth, living standards or resource allocation) to make a decision about the past, present or future regarding the relative merits of trade policy alternatives.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Arguments FOR protectionism include protecting domestic jobs and infant industries, national security considerations, and addressing unfair trade practices by other countries — though these often come at the cost of higher prices for consumers and reduced overall efficiency.", "Arguments FOR trade liberalisation include gains from specialisation (comparative advantage), increased competition driving efficiency and innovation, wider consumer choice, and lower prices — though it can cause structural unemployment in industries that can't compete internationally.", "Evaluating these trade-offs requires weighing them against criteria such as economic efficiency (whether resources are allocated to their most valuable use), economic growth (short vs long-run effects), living standards (for different groups — consumers vs. workers in protected industries), and resource allocation more broadly.", "A well-supported conclusion about trade policy typically depends on the specific context — e.g. the industry involved, the time frame considered, and which stakeholders' interests are given the most weight."]}, {"id": "3.2.5.1", "unit": 3, "topic": "T2 - Global economic issues", "subtopic": "S5 - Trade agreements", "code": "3.2.5.1", "descriptor": "Explain bilateral, regional and multilateral trade agreements that involve Australia.", "graphical": false, "needsExplanation": true, "modelAnswer": ["A bilateral trade agreement is between two countries (e.g. Australia and a single trading partner), reducing barriers specifically between those two economies.", "A regional trade agreement involves a group of countries within a geographic region (e.g. ASEAN-related agreements), reducing barriers among the member countries of that region.", "A multilateral trade agreement involves many countries globally, typically negotiated through international institutions such as the World Trade Organization, establishing broader rules-based trade liberalisation across a large number of participating economies."]}, {"id": "3.2.5.2", "unit": 3, "topic": "T2 - Global economic issues", "subtopic": "S5 - Trade agreements", "code": "3.2.5.2", "descriptor": "Explain the contemporary role of 'free trade' agreements and their impact on Australia's international trade, including trade creation and trade diversion.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Trade creation occurs when a free trade agreement leads a country to shift its purchases from a less efficient domestic producer to a more efficient producer within the trade bloc, increasing overall economic welfare/efficiency.", "Trade diversion occurs when a free trade agreement causes a country to shift its purchases from a more efficient producer OUTSIDE the bloc to a less efficient producer WITHIN the bloc (simply because the within-bloc producer now faces no tariff), which can actually reduce overall efficiency.", "Evaluating a free trade agreement's contemporary impact on Australia involves weighing whether it has predominantly created trade (efficiency gains) or diverted trade (potential efficiency losses), alongside broader effects on market access and diplomatic/strategic relationships."]}, {"id": "3.2.6.1", "unit": 3, "topic": "T2 - Global economic issues", "subtopic": "S6 - Trading bloc outcomes", "code": "3.2.6.1", "descriptor": "Analyse and evaluate the economic outcomes of international trading bloc agreements (e.g. CER, EU, NAFTA, AANZFTA) on Australian economic growth, and decide on the net benefits using economic criteria, e.g. economic efficiency, economic growth, living standards or resource allocation.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Evaluating a trading bloc's outcomes on Australian economic growth involves considering changes in export volumes/values, investment flows, and competitive pressure on domestic industries following the agreement.", "Economic criteria to weigh include: economic efficiency (whether resources shift toward Australia's areas of comparative advantage), economic growth (measurable changes in output/trade volumes), living standards (effects on consumer prices and real incomes), and resource allocation (whether the agreement encourages a more or less efficient use of Australia's productive resources).", "A 'net benefit' judgement requires balancing gains for some groups (e.g. exporters gaining new market access) against losses for others (e.g. import-competing industries facing new competition), and forming an overall conclusion about whether the agreement has been beneficial on balance."]}, {"id": "3.2.7.1", "unit": 3, "topic": "T2 - Global economic issues", "subtopic": "S7 - Communicating economic responses", "code": "3.2.7.1", "descriptor": "Create responses that communicate economic meaning using data, information, graphs and diagrams in paragraphs and extended responses to suit the intended purpose.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "4.1.1.1", "unit": 4, "topic": "T1 - Macroeconomic objectives and theory", "subtopic": "S1 - Key economic terminology", "code": "4.1.1.1", "descriptor": "Comprehend and describe key concepts using economic terminology, including basis point and percentage point changes; consumer price index; deflation; labour force underutilisation; average propensities to consume and save; non-accelerating inflation rate of unemployment; participation rate; percentage change; stagflation; structural deficit.", "graphical": false, "needsExplanation": true, "modelAnswer": ["A basis point is one-hundredth of a percentage point (0.01%), commonly used for small, precise changes in interest rates; a percentage point change is the simple arithmetic difference between two percentages (distinct from a percentage change, which expresses that difference relative to the starting value).", "The Consumer Price Index (CPI) measures the average change in prices of a fixed basket of goods and services over time, used as the primary measure of inflation; deflation is a sustained fall in the general price level (negative inflation).", "Labour force underutilisation combines unemployment and underemployment (people wanting more work hours than they currently have) into a broader measure of unused labour capacity than the unemployment rate alone.", "NAIRU (non-accelerating inflation rate of unemployment) is the theoretical unemployment rate at which inflation remains stable (neither accelerating nor decelerating); the participation rate measures the proportion of the working-age population that is in the labour force (employed or actively seeking work); stagflation describes the unusual combination of high inflation and high unemployment/stagnant growth occurring simultaneously; a structural deficit is a budget deficit that persists even when the economy is operating at its normal (potential) level of output, reflecting an underlying imbalance rather than just the current economic cycle."]}, {"id": "4.1.2.1", "unit": 4, "topic": "T1 - Macroeconomic objectives and theory", "subtopic": "S2 - Nominal vs real economic measures", "code": "4.1.2.1", "descriptor": "Distinguish nominal and real gross domestic product, wages and interest rates.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Nominal values are measured in current (unadjusted) prices, so they reflect both the actual change in quantity/output AND the effect of inflation over the period measured.", "Real values are adjusted to remove the effect of inflation, isolating the genuine change in quantity, purchasing power or output — real GDP shows actual output growth, real wages show actual purchasing power, and real interest rates show the actual return after accounting for inflation.", "Comparing nominal and real values over time reveals how much of an apparent change (e.g. rising nominal wages) is a genuine improvement versus simply a reflection of rising prices."]}, {"id": "4.1.2.2", "unit": 4, "topic": "T1 - Macroeconomic objectives and theory", "subtopic": "S2 - Nominal vs real economic measures", "code": "4.1.2.2", "descriptor": "Use calculations to identify change and scale in nominal and real gross domestic product, wages and interest rates.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "4.1.3.1", "unit": 4, "topic": "T1 - Macroeconomic objectives and theory", "subtopic": "S3 - Aggregate demand and supply factors", "code": "4.1.3.1", "descriptor": "Comprehend and explain cyclical and structural factors affecting movements and shifts of short- and long-run aggregate demand and supply.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Cyclical factors are temporary, tied to the business/economic cycle (e.g. a short-term boost in consumer confidence increasing aggregate demand), and tend to reverse as the cycle progresses.", "Structural factors reflect longer-term changes to the economy's underlying capacity or behaviour (e.g. technological change, demographic shifts, or changes in workforce skills), which shift long-run aggregate supply rather than just causing a temporary movement.", "A movement along an aggregate demand/supply curve reflects a change in the price level itself, while a shift of the curve reflects a change in one of the other underlying determinants (e.g. consumer/business confidence for AD, or productivity/input costs for AS)."]}, {"id": "4.1.4.1", "unit": 4, "topic": "T1 - Macroeconomic objectives and theory", "subtopic": "S4 - The production possibility curve", "code": "4.1.4.1", "descriptor": "Comprehend and explain the factors affecting the production possibility curve.", "graphical": false, "needsExplanation": true, "modelAnswer": ["The production possibility curve (PPC) shows the maximum combinations of two goods/services an economy can produce given its available resources and technology, assuming full and efficient use of those resources.", "An outward shift of the PPC represents economic growth in the economy's productive capacity, caused by factors such as an increase in the quantity or quality of resources (labour, capital, land), technological improvement, or increased productivity.", "An inward shift represents a decrease in productive capacity (e.g. from a natural disaster or a significant loss of resources), while a point inside the curve represents an economy not operating at its full potential (e.g. during a recession with unemployed resources)."]}, {"id": "4.1.5.1", "unit": 4, "topic": "T1 - Macroeconomic objectives and theory", "subtopic": "S5 - The multiplier effect", "code": "4.1.5.1", "descriptor": "Comprehend and explain the concept of the multiplier effect, in terms of the marginal propensity to consume and save.", "graphical": false, "needsExplanation": true, "modelAnswer": ["The multiplier effect describes how an initial injection of spending into the economy (e.g. government spending or investment) leads to a larger overall increase in national income, because that initial spending becomes someone else's income, part of which is then re-spent, and so on in successive rounds.", "The marginal propensity to consume (MPC) is the proportion of each extra dollar of income that a household spends (rather than saves); the marginal propensity to save (MPS) is the proportion saved instead (MPC + MPS = 1).", "A higher MPC (lower MPS) means more of each round of extra income gets re-spent rather than leaked into savings, resulting in a larger multiplier effect and a bigger overall boost to national income from the same initial injection."]}, {"id": "4.1.5.2", "unit": 4, "topic": "T1 - Macroeconomic objectives and theory", "subtopic": "S5 - The multiplier effect", "code": "4.1.5.2", "descriptor": "Calculate the value of the simple Keynesian multiplier, in terms of the marginal propensity to consume and save.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "4.1.6.1", "unit": 4, "topic": "T1 - Macroeconomic objectives and theory", "subtopic": "S6 - The economic cycle", "code": "4.1.6.1", "descriptor": "Comprehend and explain the four phases of the economic cycle, in the context of macroeconomic objectives.", "graphical": false, "needsExplanation": true, "modelAnswer": ["The four phases are typically described as expansion (rising output, falling unemployment), peak (economic activity at its highest point, often with inflationary pressure building), contraction/recession (falling output, rising unemployment), and trough (economic activity at its lowest point, before recovery begins).", "Each phase presents different challenges for macroeconomic objectives: expansion can risk rising inflation, while contraction risks rising unemployment — meaning the appropriate policy priority (fighting inflation vs. stimulating growth) can shift as the economy moves through the cycle.", "Governments aim to smooth the amplitude of this cycle (reducing the severity of booms and busts) using fiscal and monetary policy, rather than eliminating the cycle altogether, which is generally considered unrealistic."]}, {"id": "4.1.7.1", "unit": 4, "topic": "T1 - Macroeconomic objectives and theory", "subtopic": "S7 - Macroeconomic objectives", "code": "4.1.7.1", "descriptor": "Comprehend and explain the macroeconomic objectives of sustainable economic growth: full employment; price stability; external stability; sustainable development; and improved living standards.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Full employment does not mean zero unemployment, but rather the lowest sustainable rate of unemployment consistent with stable inflation (broadly, the NAIRU) — some frictional/structural unemployment is considered normal.", "Price stability means keeping inflation low and predictable (in Australia, the RBA targets 2–3% CPI inflation on average over time), avoiding the costs of both high inflation and deflation.", "External stability means maintaining a sustainable balance of payments position and manageable levels of foreign debt, so that Australia isn't excessively vulnerable to changes in global capital flows or currency pressures.", "Sustainable development means pursuing economic growth without unduly compromising future generations' ability to meet their own needs (balancing economic, social and environmental considerations); improved living standards refers to rising material and non-material wellbeing for the population over time."]}, {"id": "4.1.8.1", "unit": 4, "topic": "T1 - Macroeconomic objectives and theory", "subtopic": "S8 - Policy tools and economic growth", "code": "4.1.8.1", "descriptor": "Comprehend and explain how interest rates and federal budget decisions are policy tools that influence economic growth.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Interest rates (set via monetary policy by the RBA) influence economic growth by affecting the cost of borrowing and the return on saving — lower rates encourage borrowing/spending/investment (stimulating growth), while higher rates discourage them (slowing growth to contain inflation).", "Federal budget decisions (fiscal policy) influence growth through changes in government spending and taxation — increased spending or lower taxes injects more money into the economy (expansionary), while decreased spending or higher taxes withdraws money (contractionary).", "Both tools work by influencing aggregate demand in the economy, though they operate through different channels (interest rates affect borrowing/spending decisions broadly; budget decisions directly inject or withdraw government funds) and are usually coordinated to support consistent macroeconomic objectives."]}, {"id": "4.1.9.1", "unit": 4, "topic": "T1 - Macroeconomic objectives and theory", "subtopic": "S9 - The circular flow and aggregate demand", "code": "4.1.9.1", "descriptor": "Comprehend the circular flow of income model and the components of aggregate demand, focusing on economic policy decisions.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Aggregate demand is the total spending on goods and services in an economy, made up of consumption (C), investment (I), government spending (G), and net exports (exports minus imports, X−M).", "The circular flow of income model illustrates how spending by one sector becomes income for another (e.g. household consumption becomes firm revenue, which becomes wages paid to households), with leakages (savings, taxation, imports) and injections (investment, government spending, exports) determining whether the economy grows, shrinks or stays stable.", "Economic policy decisions (fiscal and monetary policy) work by deliberately altering one or more of these injections or leakages — e.g. increased government spending (G) directly raises aggregate demand, while higher interest rates tend to reduce consumption and investment (C and I)."]}, {"id": "4.1.10.1", "unit": 4, "topic": "T1 - Macroeconomic objectives and theory", "subtopic": "S10 - The aggregate demand/aggregate supply model", "code": "4.1.10.1", "descriptor": "Comprehend and explain the aggregate demand/aggregate supply model to determine the overall price level and equilibrium level of real output in an economy.", "graphical": false, "needsExplanation": true, "modelAnswer": ["The AD/AS model plots aggregate demand (total spending at each price level, generally downward sloping) against aggregate supply (total output firms are willing to produce at each price level) on axes of price level and real output.", "The equilibrium price level and equilibrium level of real output occur where the AD and AS curves intersect — at this point, the total spending in the economy exactly matches the total output being produced.", "A shift in either curve (e.g. AD increasing due to higher consumer confidence, or AS decreasing due to rising input costs) moves the equilibrium point, changing both the price level and the level of real output — the direction and relative size of these changes depends on which curve shifted and by how much."]}, {"id": "4.1.10.2", "unit": 4, "topic": "T1 - Macroeconomic objectives and theory", "subtopic": "S10 - The aggregate demand/aggregate supply model", "code": "4.1.10.2", "descriptor": "Apply the aggregate demand/aggregate supply model, including diagrams, to determine the overall price level and equilibrium level of real output in an economy.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "4.1.11.1", "unit": 4, "topic": "T1 - Macroeconomic objectives and theory", "subtopic": "S11 - Economic growth: causes, effects, benefits and costs", "code": "4.1.11.1", "descriptor": "Comprehend and explain the causes, effects, benefits and costs of sustainable economic growth to different groups and economic agents.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Causes of economic growth include increases in the quantity/quality of resources (labour, capital), improved productivity/technology, and rising aggregate demand or supply.", "Benefits typically include higher incomes and living standards, more job creation, and increased government tax revenue (without needing to raise tax rates); costs can include environmental degradation, potential inflationary pressure if growth is too rapid, and unequal distribution of the gains across different groups.", "Effects vary across economic agents — e.g. workers may benefit from more job opportunities and rising wages, businesses may benefit from higher profits and expanded markets, while environmentally sensitive industries/communities may bear more of the environmental costs of that growth."]}, {"id": "4.1.12.1", "unit": 4, "topic": "T1 - Macroeconomic objectives and theory", "subtopic": "S12 - Unemployment: causes, effects, benefits and costs", "code": "4.1.12.1", "descriptor": "Comprehend and explain the causes, effects, benefits and costs of unemployment, including cyclical, structural, frictional, seasonal, natural, hidden, long-term and underemployment, to different groups and economic agents.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Cyclical unemployment is caused by a downturn in the economic cycle (insufficient aggregate demand); structural unemployment is caused by a mismatch between workers' skills/location and available jobs (e.g. from technological change or industry decline); frictional unemployment is short-term, arising from workers being between jobs; seasonal unemployment arises from predictable seasonal fluctuations in demand for labour (e.g. agriculture, tourism).", "'Natural' unemployment refers to the unemployment rate that exists even when the economy is at full employment (combining frictional and structural unemployment); hidden unemployment includes people who want to work but aren't counted in official statistics (e.g. discouraged job seekers who've stopped actively looking); underemployment refers to people working fewer hours than they would like.", "Costs of unemployment include lost output for the economy, lower tax revenue and higher welfare spending for government, and significant personal/social costs (financial hardship, skill atrophy, mental health impacts) for the unemployed themselves — particularly severe and compounding for long-term unemployment.", "Effects and costs are not evenly distributed — structural unemployment can severely and persistently affect specific regions or industries even while the broader economy grows, illustrating how aggregate unemployment figures can mask very different experiences across different groups."]}, {"id": "4.1.13.1", "unit": 4, "topic": "T1 - Macroeconomic objectives and theory", "subtopic": "S13 - Inflation: causes, effects, benefits and costs", "code": "4.1.13.1", "descriptor": "Comprehend and explain the causes, effects, benefits and costs of inflation, including headline, underlying, demand-pull, cost-push, imported and inflation expectations, to different groups and economic agents.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Headline inflation is the raw, unadjusted measure of CPI inflation; underlying inflation strips out volatile/one-off price movements (e.g. from fuel or fresh food) to give a clearer picture of the persistent, ongoing inflation trend.", "Demand-pull inflation is caused by aggregate demand growing faster than the economy's capacity to supply goods/services ('too much money chasing too few goods'); cost-push inflation is caused by rising production costs (e.g. wages, raw materials) being passed on as higher prices; imported inflation arises from rising prices of imported goods (e.g. due to currency depreciation or global price rises); inflation expectations can become self-fulfilling if workers/businesses raise wages/prices in anticipation of future inflation.", "Costs of inflation include erosion of real purchasing power (especially harmful for those on fixed incomes), uncertainty that discourages investment, and a potential loss of international competitiveness if domestic inflation outpaces trading partners'; a small, stable, predictable rate of inflation is often considered a modest benefit, as it can encourage spending over hoarding cash and gives some flexibility for real wage adjustments.", "Different groups are affected differently — savers/lenders and those on fixed incomes tend to be disadvantaged by unexpected inflation, while borrowers can benefit (repaying debt with 'cheaper' future dollars), illustrating why inflation's overall effects depend heavily on who is being considered."]}, {"id": "4.1.14.1", "unit": 4, "topic": "T1 - Macroeconomic objectives and theory", "subtopic": "S14 - Fiscal policy and automatic stabilisers", "code": "4.1.14.1", "descriptor": "Comprehend and explain the role in fiscal policy of automatic stabilisers and the role of discretionary spending in influencing aggregate demand and stabilising the economic cycle.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Automatic stabilisers are budget items that automatically adjust with the economic cycle WITHOUT requiring new government decisions — e.g. welfare payments (like unemployment benefits) automatically rise during a downturn (supporting demand), and tax revenue automatically falls as incomes fall (leaving more money in households' hands), both cushioning the downturn.", "During an upturn, automatic stabilisers work in reverse — tax revenue rises automatically as incomes grow, and welfare payments fall as unemployment drops, automatically withdrawing some demand and helping to prevent the economy from overheating.", "Discretionary spending, in contrast, requires an active, deliberate government decision (e.g. announcing a new stimulus package or infrastructure spend) to change fiscal settings, allowing government to respond to specific circumstances beyond what automatic stabilisers alone can address."]}, {"id": "4.1.14.2", "unit": 4, "topic": "T1 - Macroeconomic objectives and theory", "subtopic": "S14 - Fiscal policy and automatic stabilisers", "code": "4.1.14.2", "descriptor": "Apply, using diagrams, the role in fiscal policy of automatic stabilisers and discretionary spending in influencing aggregate demand and stabilising the economic cycle.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "4.2.1.1", "unit": 4, "topic": "T2 - Economic indicators and past budget stances", "subtopic": "S1 - Economic indicators", "code": "4.2.1.1", "descriptor": "Explain and categorise economic indicators of past economic performance, including leading, lagging, and coincident indicators, using current data from objective sources, e.g. the Australian Bureau of Statistics and the Reserve Bank of Australia.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Leading indicators change BEFORE the overall economy changes, so they can help predict future economic activity (e.g. building approvals, business/consumer confidence surveys, share market indices).", "Lagging indicators change AFTER the overall economy has already changed, confirming a trend that has already begun (e.g. the unemployment rate, which typically continues to rise for a period even after a recovery has started).", "Coincident indicators change AT THE SAME TIME as the overall economy, reflecting the current state of economic activity in real time (e.g. GDP itself, retail sales, industrial production)."]}, {"id": "4.2.2.1", "unit": 4, "topic": "T2 - Economic indicators and past budget stances", "subtopic": "S2 - Calculating economic data", "code": "4.2.2.1", "descriptor": "Calculate the rate and changes of economic data, including real economic growth, inflation, the rate of unemployment, and the participation rate.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "4.2.3.1", "unit": 4, "topic": "T2 - Economic indicators and past budget stances", "subtopic": "S3 - Position on the economic cycle", "code": "4.2.3.1", "descriptor": "Select data and information to analyse and evaluate past economic indicators, to assess the position of the Australian economy on the economic cycle at previous points in time.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Assessing an economy's position on the cycle involves examining a combination of indicators together — e.g. rising GDP growth alongside falling unemployment and rising inflation together would typically suggest an economy nearing a cyclical peak.", "Leading indicators are particularly useful here, as they can suggest where the economy is heading even before coincident/lagging indicators fully confirm the current position.", "A sound evaluation weighs multiple indicators together (rather than relying on just one), since indicators can sometimes send mixed signals, and considers the broader context (e.g. global economic conditions) affecting how those indicators should be interpreted."]}, {"id": "4.2.4.1", "unit": 4, "topic": "T2 - Economic indicators and past budget stances", "subtopic": "S4 - Economic cycle, objectives and trade-offs", "code": "4.2.4.1", "descriptor": "Select data and information to analyse and evaluate the relationship between the economic cycle and economic objectives using past economic indicators and trade-offs, including conflicting objectives, intertemporal relationships, and the short- and long-run Phillips curve.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Conflicting objectives arise because policies that help achieve one macroeconomic objective can work against another — e.g. stimulating growth to reduce unemployment can risk higher inflation, illustrating a short-run trade-off between objectives.", "The short-run Phillips curve illustrates this specific trade-off, showing an inverse relationship between inflation and unemployment in the short run (lower unemployment associated with higher inflation, and vice versa).", "The long-run Phillips curve is generally considered vertical at the NAIRU, implying that in the long run there is no sustained trade-off — attempts to keep unemployment below the NAIRU only lead to accelerating inflation without a lasting reduction in unemployment, reflecting the intertemporal (short-run vs long-run) nature of this relationship."]}, {"id": "4.2.5.1", "unit": 4, "topic": "T2 - Economic indicators and past budget stances", "subtopic": "S5 - Accuracy and reliability of indicators", "code": "4.2.5.1", "descriptor": "Select data and information to analyse and evaluate the accuracy, reliability and efficacy of common indicators used to measure economic objectives in a past scenario.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Accuracy concerns include whether an indicator's methodology fully captures what it claims to measure — e.g. the official unemployment rate can understate the 'true' extent of joblessness because it excludes discouraged/hidden unemployed workers and underemployed workers.", "Reliability concerns include how consistently and frequently the indicator is measured, whether data revisions are common (early estimates sometimes revised substantially later), and how comparable the indicator is over time or across countries.", "Efficacy concerns whether the indicator effectively supports good policy decisions — an indicator that lags badly (like unemployment) may not give policymakers enough warning time to respond promptly to changing conditions."]}, {"id": "4.2.6.1", "unit": 4, "topic": "T2 - Economic indicators and past budget stances", "subtopic": "S6 - Federal budget outcomes", "code": "4.2.6.1", "descriptor": "Select data and information to analyse and evaluate recent Australian federal budget outcomes including cyclical and structural causes and effects of expansionary and contractionary fiscal policy stances within the last 3–10 years.", "graphical": false, "needsExplanation": true, "modelAnswer": ["An expansionary fiscal stance (increased spending and/or reduced taxes, typically running a larger deficit) aims to boost aggregate demand, often used during or after a downturn to support growth and employment.", "A contractionary fiscal stance (decreased spending and/or increased taxes, aiming for a smaller deficit or surplus) aims to reduce aggregate demand, often used to cool an overheating economy or repair the budget position after a period of expansionary spending.", "Evaluating a specific budget's stance requires distinguishing cyclical effects (e.g. automatic stabilisers responding to the current point in the economic cycle) from structural/discretionary decisions (deliberate policy choices), and assessing whether the stance achieved its stated objectives without unintended costs (e.g. excessive debt accumulation or a missed opportunity to stimulate a weak economy)."]}, {"id": "4.2.7.1", "unit": 4, "topic": "T2 - Economic indicators and past budget stances", "subtopic": "S7 - Government economic management", "code": "4.2.7.1", "descriptor": "Select data and information to analyse and evaluate the Australian Government's economic management and achievement of its macroeconomic objectives for a period within the last 3–10 years.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Evaluating economic management involves comparing actual outcomes (economic growth, unemployment, inflation, external stability) against the government's stated macroeconomic objectives and targets over the chosen period.", "This requires considering how much of the outcome was attributable to government policy decisions versus external/global factors outside the government's control (e.g. a global commodity price boom or a global financial crisis).", "A balanced evaluation acknowledges both successes (objectives met or exceeded) and shortcomings (objectives missed or trade-offs that arose), forming an overall judgement about the effectiveness of economic management over that period."]}, {"id": "4.2.8.1", "unit": 4, "topic": "T2 - Economic indicators and past budget stances", "subtopic": "S8 - Communicating economic responses", "code": "4.2.8.1", "descriptor": "Create responses that communicate economic meaning using data, information and diagrams to suit the intended purpose in paragraphs and extended responses that form an analytical essay format.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "4.3.1.1", "unit": 4, "topic": "T3 - Economic management", "subtopic": "S1 - Rationale for government intervention", "code": "4.3.1.1", "descriptor": "Comprehend and explain a rationale for the government to develop and implement economic policies that consider efficiency, equity and trade-offs, and to stabilise the economic cycle and attain a range of economic objectives including sustainable economic growth; economic prosperity and wellbeing; internal stability; external stability.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Markets can fail to deliver optimal outcomes on their own (e.g. through business cycle instability, unequal income distribution, or under-provision of public goods), giving governments a rationale to intervene through economic policy.", "Efficiency concerns whether resources are being used to produce the maximum possible value for society; equity concerns whether the outcomes and opportunities are fairly distributed across the population — policy often needs to make explicit trade-offs between the two.", "Governments use policy to try to smooth the amplitude of the economic cycle (reducing the severity of booms and recessions) and to work toward the full suite of macroeconomic objectives together, since achieving genuine economic prosperity and wellbeing typically requires progress on growth, stability and equity simultaneously, not just one objective in isolation."]}, {"id": "4.3.1.2", "unit": 4, "topic": "T3 - Economic management", "subtopic": "S1 - Rationale for government intervention", "code": "4.3.1.2", "descriptor": "Comprehend and explain demand management and supply side policies and their limitations including structural deficits, time lags, global influences and political constraints.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Demand management policies (fiscal and monetary policy) work by directly influencing the level of aggregate demand in the economy, aiming to stabilise the economic cycle in the shorter term.", "Supply-side policies work by improving the productive capacity/efficiency of the economy over the longer term (e.g. through education, infrastructure, deregulation), rather than directly managing demand.", "Limitations include time lags (the delay between a policy decision and its actual effect on the economy, which can mean a policy takes effect only after conditions have already changed), structural deficits (persistent budget imbalances that limit the government's capacity for further fiscal stimulus), global influences (external shocks or conditions beyond domestic policy's control), and political constraints (policies that are economically sound but politically difficult to implement, e.g. unpopular tax increases or spending cuts)."]}, {"id": "4.3.2.1", "unit": 4, "topic": "T3 - Economic management", "subtopic": "S2 - Fiscal policy: government revenue and expenditure", "code": "4.3.2.1", "descriptor": "Comprehend and explain the sources of government revenue (direct and indirect taxation; progressive, proportional, and regressive taxation) and the components of government expenditure (current, capital and transfer payments; public utilities and merit goods) in the federal budget.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Direct taxation is levied directly on income or wealth (e.g. personal income tax, company tax) and cannot be shifted onto someone else; indirect taxation is levied on goods/services (e.g. GST) and can be partly passed on to consumers through prices.", "A progressive tax takes a larger percentage of income from higher-income earners (e.g. Australia's personal income tax scale); a proportional tax takes the same percentage from all income levels; a regressive tax takes a larger percentage of income from lower-income earners (often indirect taxes like GST have this effect relative to income, since lower earners spend a larger share of their income on consumption).", "Current expenditure covers the government's day-to-day running costs (e.g. wages, ongoing services); capital expenditure funds long-term assets (e.g. infrastructure); transfer payments redistribute income without directly purchasing goods/services (e.g. welfare payments); spending on public utilities and merit goods (e.g. healthcare, education) reflects government provision of goods/services considered to be under-provided by the private market alone."]}, {"id": "4.3.2.2", "unit": 4, "topic": "T3 - Economic management", "subtopic": "S2 - Fiscal policy: government revenue and expenditure", "code": "4.3.2.2", "descriptor": "Analyse and evaluate the impact and/or effectiveness of fiscal policy responses to achieve Australia's economic objectives in the future.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Evaluating a proposed fiscal policy response involves projecting its likely effect on aggregate demand, and therefore on growth, employment and inflation, weighed against the specific macroeconomic objectives it targets.", "Effectiveness depends on factors such as the size of the fiscal multiplier for that type of spending/tax change, the timing and speed of implementation (given fiscal policy can be subject to significant time lags), and how the policy interacts with other current settings (e.g. monetary policy working in a complementary or offsetting direction).", "A thorough evaluation also weighs potential costs — such as effects on the structural budget position, public debt sustainability, and whether the fiscal response could crowd out private sector activity — against its intended benefits."]}, {"id": "4.3.3.1", "unit": 4, "topic": "T3 - Economic management", "subtopic": "S3 - The Reserve Bank and monetary policy objectives", "code": "4.3.3.1", "descriptor": "Comprehend and explain the role of the Reserve Bank of Australia (RBA) and the objectives of monetary policy as outlined in its charter.", "graphical": false, "needsExplanation": true, "modelAnswer": ["The RBA is Australia's central bank, responsible for setting monetary policy (primarily via the cash rate target) independently of the elected government.", "Its charter objectives are typically framed around price stability (inflation targeting), full employment, and the economic prosperity and welfare of the Australian people — a broader mandate than inflation control alone.", "The RBA pursues these objectives through its control over the cash rate and other monetary policy tools, aiming to influence broader financial conditions (interest rates, credit growth, the exchange rate) to steer the economy toward its objectives."]}, {"id": "4.3.4.1", "unit": 4, "topic": "T3 - Economic management", "subtopic": "S4 - Inflation targeting", "code": "4.3.4.1", "descriptor": "Comprehend, explain, analyse and evaluate the concept of inflation targeting and the significance of monetary policy on the level of economic activity, and include a discussion of percentage change and basis point change.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Inflation targeting means the central bank sets and pursues an explicit numerical target for inflation (in Australia, 2–3% average CPI inflation over the cycle), using this target to anchor its interest rate decisions.", "By committing to and communicating a clear target, the RBA aims to keep inflation expectations well-anchored among businesses and households, which itself helps keep actual inflation stable (since expectations influence wage/price-setting behaviour).", "Monetary policy changes are often described using basis points (e.g. a '25 basis point' interest rate rise/cut, meaning 0.25 percentage points) because interest rate movements are typically small, and precise basis-point language avoids the ambiguity of describing a movement as a 'percentage change' (which would refer to the relative, not absolute, size of the movement)."]}, {"id": "4.3.4.2", "unit": 4, "topic": "T3 - Economic management", "subtopic": "S4 - Inflation targeting", "code": "4.3.4.2", "descriptor": "Comprehend, explain, analyse and evaluate the transmission mechanism and channels of monetary policy, and their influence on the level of aggregate demand.", "graphical": false, "needsExplanation": true, "modelAnswer": ["The transmission mechanism describes the chain of effects through which a change in the cash rate flows through to the broader economy and eventually to aggregate demand.", "Key channels include the interest rate channel (changed borrowing/saving incentives affecting consumption and investment directly), the exchange rate channel (interest rate changes affecting capital flows and thus the currency, which affects net exports), the asset price channel (interest rates affecting the value of assets like housing and shares, influencing wealth and spending), and the expectations/confidence channel (interest rate changes signalling the RBA's view of the economy, influencing business/consumer confidence).", "These channels operate with varying time lags and strengths, meaning the overall effect of a monetary policy change on aggregate demand can take considerable time to be fully realised, and its size can be uncertain in advance."]}, {"id": "4.3.4.3", "unit": 4, "topic": "T3 - Economic management", "subtopic": "S4 - Inflation targeting", "code": "4.3.4.3", "descriptor": "Comprehend, explain, analyse and evaluate the impact on and/or effectiveness of monetary policy responses to achieve Australia's economic objectives.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Evaluating monetary policy's effectiveness involves considering how reliably and predictably changes in the cash rate translate through the transmission mechanism into changes in aggregate demand, inflation and employment.", "Effectiveness can be limited by factors such as time lags (delays before the full effect is felt), the degree of household/business sensitivity to interest rate changes (e.g. how much of the population holds variable-rate mortgages), and constraints such as the 'zero lower bound' on interest rates in very weak economic conditions.", "A balanced evaluation weighs monetary policy's relative strengths (faster to adjust than fiscal policy, operated independently of political pressure) against its limitations, often in the context of how well it has worked alongside fiscal policy to achieve Australia's broader economic objectives."]}, {"id": "4.3.5.1", "unit": 4, "topic": "T3 - Economic management", "subtopic": "S5 - Supply-side and microeconomic policy", "code": "4.3.5.1", "descriptor": "Comprehend and describe the nature and aims of aggregate supply policies (including microeconomic reforms) and explain their relationship to domestic macroeconomic objectives.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Aggregate supply policies aim to increase the economy's productive capacity and efficiency over the longer term, rather than directly managing short-term demand fluctuations.", "Microeconomic reforms are a key category of supply-side policy, targeting specific markets or industries to remove inefficiencies (e.g. deregulating an industry, increasing competition, reforming labour markets) so resources can be used more productively.", "These policies relate to macroeconomic objectives by supporting sustainable, non-inflationary economic growth over time — by expanding the economy's capacity to produce, supply-side reforms can help achieve higher output and lower unemployment without necessarily generating the inflationary pressure that purely demand-driven growth might cause."]}, {"id": "4.3.5.2", "unit": 4, "topic": "T3 - Economic management", "subtopic": "S5 - Supply-side and microeconomic policy", "code": "4.3.5.2", "descriptor": "Comprehend and explain how a government policy focused on a supply side improvement can impact Australia's economic growth through productivity, efficiency or competitiveness, using infrastructure; education and training; research and development; innovation, and deregulation.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Infrastructure investment (transport, communications, utilities) can lower business costs and improve the efficient movement of goods, people and information, boosting productivity across the economy.", "Education and training improve the skills and productivity of the workforce (human capital), enabling workers to produce more value per hour worked and adapt more readily to changing industry needs.", "Research and development, and innovation more broadly, can generate new products, processes and technologies that raise productivity and open up new areas of competitive advantage for Australian firms.", "Deregulation (removing unnecessary rules/restrictions in a market) can increase competition and efficiency, though it needs to be balanced against the risk of removing regulation that served a genuinely important protective purpose."]}, {"id": "4.3.5.3", "unit": 4, "topic": "T3 - Economic management", "subtopic": "S5 - Supply-side and microeconomic policy", "code": "4.3.5.3", "descriptor": "Analyse and evaluate the impact of and/or effectiveness of policy responses to achieve Australia's economic objectives.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Evaluating supply-side policy effectiveness involves considering the (often long) time lag before productivity/efficiency gains are realised, compared with the more immediate effects typically associated with demand management policy.", "Effectiveness can depend on how well-targeted the specific reform is to a genuine structural weakness in the economy, and the scale of investment or reform relative to the size of the problem being addressed.", "A balanced evaluation weighs the longer-term, supply-side benefits (sustainable growth in productive capacity) against the upfront costs and the fact that outcomes may not be visible or measurable for some years, making effectiveness harder to assess in the short term compared with demand-side policy."]}];
